/**
 * A sent email's Klaviyo results (Graeme, 2026-10-26): "the amount of orders
 * placed and the revenue generated by those orders by that email ... the
 * full open rate, click rate, and placed order rate with the actual values
 * below" — the same three columns as Klaviyo's campaigns table.
 */
import { cn } from "@/lib/utils";
import type { EmailResults } from "./api";

const pct = (n: number) => `${(n * 100).toFixed(2)}%`;
const num = (n: number) => n.toLocaleString("en-GB");
const gbp = (n: number) => `£${n.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const gbp0 = (n: number) => `£${Math.round(n).toLocaleString("en-GB")}`;

/** Three big columns — the email's detail panel and the agenda rows. */
export function EmailResultsBlock({ r, compact = false }: { r: EmailResults; compact?: boolean }) {
  const cols = [
    { label: "Open rate", value: pct(r.openRate), sub: `${num(r.opens)} recipients` },
    { label: "Click rate", value: pct(r.clickRate), sub: `${num(r.clicks)} recipients` },
    { label: "Placed order", value: gbp(r.revenue), sub: `${num(r.orders)} order${r.orders === 1 ? "" : "s"} · ${pct(r.orderRate)}`, strong: true },
  ];
  return (
    <div className={cn("grid grid-cols-3 gap-2", compact ? "text-left" : "rounded-xl border border-border p-3")}>
      {cols.map(c => (
        <div key={c.label} className="min-w-0">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">{c.label}</p>
          <p className={cn("font-bold tabular-nums leading-tight", compact ? "text-base" : "text-xl", c.strong ? "text-primary" : "text-foreground")}>{c.value}</p>
          <p className="text-xs text-muted-foreground tabular-nums">{c.sub}</p>
        </div>
      ))}
    </div>
  );
}

/** One line for a month-grid chip: "£284 · 5 orders". */
export function emailResultsChip(r: EmailResults): string {
  return `${gbp0(r.revenue)} · ${num(r.orders)} order${r.orders === 1 ? "" : "s"}`;
}
